impl Solution{pub fn strobogrammatic_in_range(lo:String,hi:String)->i32{fn f(s:&mut Vec<u8>,l:i32,r:i32,lo:&str,hi:&str,c:&mut i32){let p=[(b'0',b'0'),(b'1',b'1'),(b'6',b'9'),(b'8',b'8'),(b'9',b'6')];if l>r{let x=String::from_utf8(s.clone()).unwrap();if (x.len()>lo.len()||x.as_str()>=lo)&&(x.len()<hi.len()||x.as_str()<=hi){*c+=1}return}for &(a,b)in&p{if l==0&&s.len()>1&&a==b'0'{continue}if l==r&&a!=b{continue}s[l as usize]=a;s[r as usize]=b;f(s,l+1,r-1,lo,hi,c)}}let mut c=0;for n in lo.len()..=hi.len(){f(&mut vec![b' ';n],0,n as i32-1,&lo,&hi,&mut c);}c}}
